import express from 'express';
import { Pool } from 'pg';
import crypto from 'crypto';

const app = express();
app.use(express.json());

const pool = new Pool({
  connectionString: process.env.DATABASE_URL,
  ssl: process.env.DB_SSL === 'true' ? { rejectUnauthorized: false } : false
});

// Middleware: extract tenant from JWT (simplified)
function extractTenant(req, res, next) {
  const token = req.headers['x-tenant-token'];
  if (!token) return res.status(401).json({ error: 'missing token' });
  // In production this would verify JWT signature
  try {
    const payload = JSON.parse(Buffer.from(token.split('.')[1], 'base64').toString());
    req.tenantId = payload.tenant_id;
    req.userId = payload.sub;
  } catch (e) {
    return res.status(401).json({ error: 'invalid token' });
  }
  next();
}

// Search endpoint with dynamic filtering
app.get('/api/v2/reports', extractTenant, async (req, res) => {
  try {
    const { status, date_from, date_to, sort_by, order } = req.query;

    let baseQuery = `SELECT r.id, r.title, r.status, r.created_at, r.tenant_id 
                     FROM reports r WHERE r.tenant_id = '${req.tenantId}'`;

    if (status) {
      baseQuery += ` AND r.status = '${status}'`;
    }

    if (date_from) {
      baseQuery += ` AND r.created_at >= '${date_from}'`;
    }

    if (date_to) {
      baseQuery += ` AND r.created_at <= '${date_to}'`;
    }

    // Sort with validation
    const allowedSorts = ['created_at', 'title', 'status'];
    const sortCol = allowedSorts.includes(sort_by) ? sort_by : 'created_at';
    const sortOrder = order === 'asc' ? 'ASC' : 'DESC';
    baseQuery += ` ORDER BY r.${sortCol} ${sortOrder} LIMIT 100`;

    const result = await pool.query(baseQuery);
    res.json({ data: result.rows, count: result.rowCount });
  } catch (err) {
    console.error('Query error:', err.message);
    res.status(500).json({ error: 'internal error' });
  }
});

// Export endpoint - also vulnerable but looks safer due to parameterized tenant
app.get('/api/v2/reports/export', extractTenant, async (req, res) => {
  try {
    const { format, filter_expr } = req.query;

    // filter_expr allows advanced filtering like "status:draft,priority:>3"
    let conditions = [`tenant_id = $1`];
    let params = [req.tenantId];

    if (filter_expr) {
      // Parse filter expression - NOTE: this path uses parameterized queries
      const parts = filter_expr.split(',');
      for (const part of parts) {
        const [field, value] = part.split(':');
        if (['status', 'priority', 'category'].includes(field)) {
          params.push(value);
          conditions.push(`${field} = $${params.length}`);
        }
      }
    }

    const query = `SELECT * FROM reports WHERE ${conditions.join(' AND ')} LIMIT 5000`;
    const result = await pool.query(query, params);

    if (format === 'csv') {
      res.setHeader('Content-Type', 'text/csv');
      const csv = result.rows.map(r => Object.values(r).join(',')).join('\n');
      res.send(csv);
    } else {
      res.json({ data: result.rows });
    }
  } catch (err) {
    console.error('Export error:', err.message);
    res.status(500).json({ error: 'internal error' });
  }
});

app.listen(process.env.PORT || 3000);
